from playwright.sync_api import sync_playwright
import subprocess, time, sys
srv = subprocess.Popen([sys.executable, 'run_server.py'], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL); time.sleep(2)
errs = []; B = 'http://127.0.0.1:5057'
def ok(c, m):
    print('OK   ' if c else 'FALLA', m)
    if not c: raise SystemExit(1)
try:
  with sync_playwright() as p:
    b = p.chromium.launch(); ctx = b.new_context(viewport={'width': 1200, 'height': 800}); pg = ctx.new_page()
    pg.on('console', lambda m: errs.append(m.text) if m.type == 'error' else None); pg.on('pageerror', lambda e: errs.append(str(e)))
    pg.goto(B + '/'); pg.wait_for_selector('.hero'); ok('Usa la IA' in pg.inner_text('h1'), 'Inicio carga'); pg.screenshot(path='s01_inicio.png')
    pg.goto(B + '/#/dashboard'); pg.wait_for_selector('#correo'); ok('#/login' in pg.url, 'Ruta protegida lleva a login')
    pg.fill('#correo', 'x@y.com'); pg.fill('#contrasena', 'malapass'); pg.click('button[type=submit]'); pg.wait_for_selector('.msg.err')
    ok('incorrectos' in pg.inner_text('.msg.err'), 'Login incorrecto muestra error'); pg.screenshot(path='s02_login_error.png')
    pg.click('text=Regístrate'); pg.wait_for_selector('#nombre_completo')
    pg.click('button[type=submit]'); ok(pg.is_visible('.msg.err'), 'Registro vacío muestra error')
    pg.fill('#nombre_completo', 'Saúl Angulo Posadas'); pg.fill('#correo', 'saul@correo.com'); pg.fill('#contrasena', 'secreto1'); pg.fill('#confirmar_contrasena', 'secreto2')
    pg.check('#acepto'); pg.click('button[type=submit]'); pg.wait_for_selector('.msg.err'); ok('no coinciden' in pg.inner_text('.msg.err'), 'Contraseñas distintas')
    pg.fill('#confirmar_contrasena', 'secreto1'); pg.screenshot(path='s03_registro.png'); pg.click('button[type=submit]'); pg.wait_for_selector('.kpis')
    ok('#/dashboard' in pg.url and 'Bienvenido, Saúl' in pg.inner_text('h1'), 'Registro -> dashboard con sesión'); ok('0%' in pg.inner_text('.k1'), 'KPI avance 0%')
    pg.screenshot(path='s04_dashboard0.png')
    pg.click('a:has-text("Continuar lección")'); pg.wait_for_selector('.lec-body'); ok('IA generativa' in pg.inner_text('h1'), 'Continuar lección abre la lección 1')
    pg.click('text=Marcar como completada'); pg.wait_for_selector('.msg.ok'); ok('12%' in pg.inner_text('.msg.ok') or '13%' in pg.inner_text('.msg.ok'), 'Completar lección actualiza avance'); pg.screenshot(path='s05_leccion.png')
    pg.click('text=Siguiente ›'); pg.wait_for_function("document.querySelector('h1') && document.querySelector('h1').innerText.includes('Plagio')"); ok('Plagio' in pg.inner_text('h1'), 'Siguiente lección')
    pg.click('a:has-text("Mis cursos")'); pg.wait_for_selector('.curso'); ok(pg.locator('.curso').count() == 3, '3 cursos'); pg.screenshot(path='s06_cursos.png')
    pg.click('.chip:has-text("Privacidad")'); ok(pg.locator('.curso').count() == 1, 'Filtro por categoría')
    pg.click('.curso a.btn'); pg.wait_for_selector('.lecs'); ok(pg.locator('.lecs li').count() == 3, 'Curso con 3 lecciones'); pg.screenshot(path='s07_curso.png')
    pg.click('a:has-text("Normatividad")'); pg.wait_for_selector('.lista-n a'); ok(pg.locator('.lista-n a').count() == 6, '6 normas')
    pg.fill('.docs ~ * , form.card input[type=search]', 'plagio') if False else pg.fill('form.card input[type=search]', 'plagio'); pg.click('form.card button[type=submit]'); pg.wait_for_function("document.querySelectorAll('.lista-n a').length===1")
    pg.click('.lista-n a'); pg.wait_for_selector('.si'); ok('SÍ hacer' in pg.inner_text('.si') and 'NO hacer' in pg.inner_text('.no'), 'Guía Sí/No hacer'); pg.screenshot(path='s08_normas.png')
    pg.fill('.bar-top input', 'datos'); pg.press('.bar-top input', 'Enter'); pg.wait_for_function("location.hash.includes('q=datos')"); pg.wait_for_function("(document.querySelector('form.card input[type=search]')||{}).value==='datos' && document.querySelectorAll('.lista-n a').length>=1"); ok(pg.locator('.lista-n a').count() >= 1, 'Buscador de la barra superior')
    pg.click('a:has-text("Mi progreso")'); pg.wait_for_selector('table'); ok('Avance global' in pg.inner_text('.card h2'), 'Mi progreso'); pg.screenshot(path='s09_progreso.png')
    pg.click('a:has-text("Mi perfil")'); pg.wait_for_selector('#institucion'); ok(pg.input_value('#correo') == 'saul@correo.com', 'Perfil precargado')
    pg.fill('#institucion', 'Instituto Tecnológico'); pg.fill('#biografia', 'Interesado en la IA ética.'); pg.click('text=Guardar cambios'); pg.wait_for_selector('.msg.ok'); pg.screenshot(path='s10_perfil.png')
    pg.reload(); pg.wait_for_selector('#institucion'); ok(pg.input_value('#institucion') == 'Instituto Tecnológico', 'Perfil persiste tras recargar')
    pg.click('a:has-text("Dashboard")'); pg.wait_for_selector('.kpis'); ok('Instituto' not in pg.inner_text('.kpis') and '13%' in pg.inner_text('.k1') or '12%' in pg.inner_text('.k1'), 'Dashboard refleja el avance'); ok('1' in pg.inner_text('.k4'), 'Normas consultadas > 0')
    pg.click('button:has-text("Cerrar sesión")'); pg.wait_for_selector('.hero'); ok(pg.is_visible('text=Iniciar sesión'), 'Cerrar sesión vuelve al inicio')
    pg.goto(B + '/#/perfil'); pg.wait_for_selector('#correo'); ok('#/login' in pg.url, 'Sin sesión no entra al perfil')
    pg.fill('#correo', 'SAUL@correo.com'); pg.fill('#contrasena', 'secreto1'); pg.click('button[type=submit]'); pg.wait_for_selector('.kpis'); ok(True, 'Login correcto')
    m = ctx.new_page(); m.set_viewport_size({'width': 390, 'height': 800}); m.goto(B + '/#/dashboard'); m.wait_for_selector('.kpis')
    ok(m.evaluate('document.documentElement.scrollWidth <= window.innerWidth + 1'), 'Móvil: sin desplazamiento horizontal'); m.screenshot(path='s11_movil.png', full_page=True)
    b.close()
finally:
    srv.terminate()
print('\nErrores de consola:', errs if errs else 'ninguno')
